/**
 * A class that allows for the reuse of native demangler executable processes.  This class will
 * cache the process by name and by any arguments passed to the process when started.  Once
 * successfully started, the process will persist
 */
public class GnuDemanglerNativeProcess {
	public static readonly string DEMANGLER_GNU = GnuDemanglerOptions.GNU_DEMANGLER_DEFAULT;

	private static readonly string DEFAULT_NATIVE_OPTIONS = "";
	private static readonly Map<string, GnuDemanglerNativeProcess> processesByName =
		new();
	
	private static bool errorDisplayed = false;
	
	private static bool getAndSetErrorDisplayed() {
		bool b = errorDisplayed;
		if (!b) {
			errorDisplayed = true;
		}
		return b;
	}

	private string applicationName;
	private string options;

	private bool isDisposed;
	private Process process;
	private BufferedReader reader;
	private PrintWriter writer;

	/**
	 * Gets the default GNU demangler native process
	 * @return the process
	 * @throws IOException if the process cannot be started
	 */
	public static GnuDemanglerNativeProcess getDemanglerNativeProcess()
    {
		return getDemanglerNativeProcess(DEMANGLER_GNU);
	}

	/**
	 * Gets the default GNU demangler native process
	 * @param name the specific executable name to launch
	 * @return the process
	 * @throws IOException if the process cannot be started
	 */
	public static GnuDemanglerNativeProcess getDemanglerNativeProcess(string name)
    {

		return getDemanglerNativeProcess(name, DEFAULT_NATIVE_OPTIONS);
	}

	/**
	 * Gets the default GNU demangler native process
	 * @param name the specific executable name to launch
	 * @param nativeOptions the arguments string to pass to the native demangler
	 * @return the process
	 * @throws IOException if the process cannot be started
	 */
	public static GnuDemanglerNativeProcess getDemanglerNativeProcess(string name,
			string nativeOptions)
    {

		string options = nativeOptions;
		if (StringUtils.isBlank(options)) {
			options = DEFAULT_NATIVE_OPTIONS;
		}

		string key = getKey(name, options);
		GnuDemanglerNativeProcess nativeProcess = processesByName.get(key);
		if (nativeProcess == null) {
			nativeProcess = new GnuDemanglerNativeProcess(name, options);
		}
		return nativeProcess;
	}

	private static string getKey(string name, string options) {
		return name + ' ' + options;
	}

	private GnuDemanglerNativeProcess(string applicationName, string options)
    {
		this.applicationName = applicationName;
		this.options = options;
		createProcess();
	}

	/**
	 * {@return the demangled string}
	 * 
	 * @param mangled The string to demangle
	 * @throws IOException if an IO-related error occurred
	 */
	public string demangle(string mangled)
    {
		return demangle(mangled, true, null);
	}

	/**
	 * {@return the demangled string}
	 * 
	 * @param mangled The string to demangle
	 * @param timeoutSeconds The number of seconds to attempt the demangle, or {@code null} for no
	 *   timeout
	 * @throws IOException if a timeout or IO-related error occurred
	 */
	public string demangle(string mangled, Long timeoutSeconds)
    {
		if (isDisposed) {
			throw new IOException("Demangled process has been terminated.");
		}
		return demangle(mangled, true, timeoutSeconds);
	}

	private string demangle(string mangled, bool restart, Long timeoutSeconds)
    {
		try {
			return doDemangle(mangled, timeoutSeconds);
		}
		catch (TimeoutException e) {
			dispose();
			throw new IOException("Timeout reached", e);
		}
		catch (IOException e) {
			dispose();
			if (!restart) {
				throw new IOException("Demangler process is not running.", e);
			}
			createProcess();
			return demangle(mangled, false, timeoutSeconds);
		}
	}

	private string doDemangle(string mangled, Long timeoutSeconds)
    {
		writer.println(mangled);
		writer.flush();
		try {
			return timeoutSeconds != null
					? SimpleTimeLimiter
							.create(AutoAnalysisManager.getSharedAnalsysThreadPool()
									.getExecutorService())
							.callWithTimeout(reader.readLine, timeoutSeconds, TimeUnit.SECONDS)
					: reader.readLine();
		}
		catch (Exception e) when (e is ExecutionException or InterruptedException) {
			throw new IOException(e);
		}
	}

	public void dispose() {

		string key = getKey(applicationName, options);
		processesByName.remove(key);

		try {
			if (process != null) {
				process.destroy();
			}
			process = null;
			reader = null;
			writer = null;
		}
		catch (Exception e) {
			// ignore
		}
		finally {
			isDisposed = true;
		}
	}

	/* @SuppressWarnings("resource") */
	private void createProcess()
    {

		string[] command = buildCommand();
		IOException exc = null;
		isDisposed = true;
		try {
			process = Runtime.getRuntime().exec(command);
			InputStream @in= process.getInputStream();
			OutputStream @out = process.getOutputStream();
			reader = new BufferedReader(new InputStreamReader(@in));
			writer = new PrintWriter(@out);
			
			checkForError(command);
			
			isDisposed = false;
		}
		catch (IOException e) {
			exc = e;
		}
		finally {
			if (isDisposed) {
				if (process != null) {
					process.destroy();
				}
				if (!getAndSetErrorDisplayed()) {
					string errorDetail = "";
					if (exc != null) {
						errorDetail = exc.getMessage();
					}
					errorDetail = "GNU Demangler executable may not be compatible with your system and may need to be rebuilt.\n" +
							"(see GettingStarted.md, 'Building Native Components').\n\n" +
							errorDetail;		
					Msg.showError(this, null, "Failed to launch GNU Demangler process", errorDetail);
				}
				if (exc == null) {
					throw new IOException("GNU Demangler process failed to launch (see log for details)");
				}
				throw exc;
			}
		}

		string key = getKey(applicationName, options);
		processesByName.put(key, this);
	}

	private string[] buildCommand()
    {

		string executableName =
			applicationName + Platform.CURRENT_PLATFORM.getExecutableExtension();
		File commandPath = Application.getOSFile(executableName);

		string[] command = new string[] { commandPath.getAbsolutePath() };
		if (!StringUtils.isBlank(options)) {
			string[] optionsArray = options.split("\\s");
			command = ArrayUtils.addAll(command, optionsArray);
		}
		return command;
	}

	private void checkForError(string[] command)
    {

		//
		// We do not want to read the error stream in the happy path case, as that will block.
		// Send a test string over and read the result.   If the test string is blank, then
		// there was an error.
		//
		try {
			string testResult = doDemangle("test", null);
			if (!StringUtils.isBlank(testResult)) {
				return;
			}
		}
		catch (TimeoutException e) {
			throw new IOException(e);
		}

		InputStream err = process.getErrorStream();
		string error = null;
		try {
			List<string> errorLines = IOUtils.readLines(err, Charset.defaultCharset());
			error = StringUtils.join(errorLines, '\n');
		}
		catch (UncheckedIOException e) {
			throw new IOException("Unable to read process error stream: ", e);
		}

		if (StringUtils.isBlank(error)) {
			return;
		}

		string executable = command[0];
		string baseName = FilenameUtils.getBaseName(executable);
		command[0] = baseName;

		// cleanup full path, as it is ugly in the error message
		error = error.replace(executable, "");
		throw new IOException("Error starting demangler with command: '" +
			Arrays.toString(command) + "' " + error);
	}
}
